306	/** A declared repository entry that maps two folder names to one label. */
307	const declaredRepo = {
308	  id: 'ai-insights',
309	  label: 'AI Insights',
310	  folder_names: ['ai-insights', 'ai-insights-dev'],
311	};
312	
313	/**
314	 * A project whose repository_name matches the first folder_name of declaredRepo.
315	 * The "Repository" column should show "AI Insights" (the label), not "ai-insights".
316	 */
317	const projectMatchingFolder = {
318	  slug: '2026-05-label-plan',
319	  project_name: 'Label Plan',
320	  repository_name: 'ai-insights',
321	  status: 'IN_PROGRESS',
322	  runner: 'vscode',
323	  total_work_packages: 2,
324	  progress_pct: 50,
325	  date_created: '2026-05-01T00:00:00Z',
326	  last_updated: '2026-05-10T00:00:00Z',
327	};
328	
329	/**
