331	 * Should display the same label as projectMatchingFolder.
332	 */
333	const projectMatchingAltFolder = {
334	  slug: '2026-05-label-plan-dev',
335	  project_name: 'Label Plan Dev',
336	  repository_name: 'ai-insights-dev',
337	  status: 'READY',
338	  runner: 'vscode',
339	  total_work_packages: 1,
340	  progress_pct: 0,
341	  date_created: '2026-05-02T00:00:00Z',
342	  last_updated: '2026-05-11T00:00:00Z',
343	};
344	
345	/**
346	 * A project whose repository_name does NOT match any declared repository.
347	 * The "Repository" column should display the raw folder name (no substitution).
348	 */
349	const projectUnregisteredFolder = {
350	  slug: '2026-05-unregistered',
351	  project_name: 'Unregistered Plan',
352	  repository_name: 'some-other-repo',
353	  status: 'READY',
354	  runner: 'vscode',
355	  total_work_packages: 0,
356	  progress_pct: 0,
357	  date_created: '2026-05-03T00:00:00Z',
358	  last_updated: '2026-05-12T00:00:00Z',
359	};
