361	describe('buildTable — repository label resolution (WP-010)', () => {
362	  // AC-1: folder name that matches a declared repo → label replaces raw folder name
363	  it('displays the declared label when folder_name matches a registry entry', async () => {
364	    const app = await renderList([projectMatchingFolder], [declaredRepo]);
365	
366	    const repoCells = app.querySelectorAll('td.repo-col');
367	    expect(repoCells.length).toBeGreaterThan(0);
368	
369	    const repoCell = repoCells[0] as HTMLElement;
370	    expect(repoCell.textContent).toBe(declaredRepo.label);
371	    // Should NOT show the raw folder name as text
372	    expect(repoCell.textContent).not.toBe(projectMatchingFolder.repository_name);
373	
374	    document.body.removeChild(app);
375	  });
376	
377	  // AC-1 extended: label links to #/strategy/:repoId
378	  it('label is a link pointing to #/strategy/:repoId', async () => {
379	    const app = await renderList([projectMatchingFolder], [declaredRepo]);
380	
381	    const repoCell = app.querySelector('td.repo-col') as HTMLElement;
382	    const link = repoCell.querySelector('a') as HTMLAnchorElement | null;
383	    expect(link).not.toBeNull();
384	    expect(link!.getAttribute('href')).toBe('#/strategy/' + encodeURIComponent(declaredRepo.id));
385	
386	    document.body.removeChild(app);
387	  });
388	
389	  // AC-2: folder name NOT in any declared repo → displays raw folder name (no regression)
390	  it('displays the raw folder name when no registry entry matches', async () => {
391	    const app = await renderList([projectUnregisteredFolder], [declaredRepo]);
392	
393	    const repoCell = app.querySelector('td.repo-col') as HTMLElement;
394	    // No link — plain text with the raw folder name
395	    const link = repoCell.querySelector('a');
396	    expect(link).toBeNull();
397	    expect(repoCell.textContent).toBe(projectUnregisteredFolder.repository_name);
398	
399	    document.body.removeChild(app);

400	  });
401	
402	  // AC-2: unmatched project still shows raw folder name even when registry has entries
403	  it('does not corrupt unmatched rows when a registry is present', async () => {
404	    const app = await renderList(
405	      [projectMatchingFolder, projectUnregisteredFolder],
406	      [declaredRepo],
407	    );
408	
409	    const repoCells = app.querySelectorAll('td.repo-col');
410	    expect(repoCells.length).toBe(2);
411	
412	    // First row: matched → label
413	    expect(repoCells[0].textContent).toBe(declaredRepo.label);
414	    // Second row: unmatched → raw folder name
415	    expect(repoCells[1].textContent).toBe(projectUnregisteredFolder.repository_name);
416	
417	    document.body.removeChild(app);
418	  });
419	
420	  // AC-3: two projects from different folder_names of the SAME declared repo → same label
421	  it('shows the same label for projects from different folder_names of one declared repo', async () => {
422	    const app = await renderList(
423	      [projectMatchingFolder, projectMatchingAltFolder],
424	      [declaredRepo],
425	    );
426	
427	    const repoCells = app.querySelectorAll('td.repo-col');
428	    expect(repoCells.length).toBe(2);
429	
430	    // Both rows should display the same declared label
431	    expect(repoCells[0].textContent).toBe(declaredRepo.label);
432	    expect(repoCells[1].textContent).toBe(declaredRepo.label);
433	
434	    document.body.removeChild(app);
435	  });
436	
437	  // Graceful degradation: if listRepos fails, raw folder names are shown (no crash)
438	  it('falls back to raw folder names when the repos endpoint fails', async () => {
439	    const app = document.createElement('div');
440	    document.body.appendChild(app);
441	
442	    (globalThis as any).fetch = vi.fn(async (url: string) => {
443	      if (String(url).includes('/api/repos')) {
444	        // Simulate a network error for the repos endpoint
445	        throw new Error('Network error');
446	      }
447	      return {
448	        ok: true,
449	        status: 200,
450	        json: async () => makeEnvelope([projectMatchingFolder]),
451	      };
452	    });
453	
454	    globalThis.renderProjectList(app);
455	    await new Promise(r => setTimeout(r, 20));
456	
457	    const repoCell = app.querySelector('td.repo-col') as HTMLElement;
458	    // Should fall back to raw folder name, not crash
459	    expect(repoCell).not.toBeNull();

460	    expect(repoCell.textContent).toBe(projectMatchingFolder.repository_name);
461	
462	    document.body.removeChild(app);
463	  });
464	});
465	
466	describe('action-menu portal handler — skips when data-repo is empty', () => {
467	  it('logs an error and does NOT call API.deleteProject for null-repo projects', async () => {
468	    const app = await renderList([projectWithoutRepo]);
469	
